"""Authorization center UI. Secrets are never returned to the browser."""

from .theme import theme_head


def authorizations_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head>''' + theme_head() + r'''<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>授权中心 · 影舟 MovieArk</title><style>
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,var(--accent-soft),var(--bg-deep) 45%);color:var(--text-primary);font:14px system-ui,"Microsoft YaHei",sans-serif}.shell{display:grid;grid-template-columns:235px 1fr;min-height:100vh}.side{padding:20px 12px;background:var(--sidebar-bg);border-right:1px solid var(--line)}.logo{font-size:21px;font-weight:800;color:var(--gold);padding:6px 10px 28px}.nav{display:block;padding:13px 15px;color:var(--text-secondary);text-decoration:none;border-radius:12px;font-weight:700}.nav:hover,.nav.active{background:var(--hover-bg);color:var(--accent-primary)}.group{color:var(--text-muted);font-size:11px;border-bottom:1px solid var(--border-secondary);padding:16px 8px 7px;margin-bottom:5px}.top{height:64px;padding:0 28px;display:flex;align-items:center;border-bottom:1px solid var(--line);font-size:22px;font-weight:800;color:var(--cyan)}.wrap{max-width:1350px;margin:auto;padding:24px}.intro{color:var(--muted);margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{border:1px solid var(--line);border-radius:15px;background:var(--card);padding:20px}.head{display:flex;align-items:center;gap:10px}.head h2{margin:0;color:var(--gold)}.status{margin-left:auto;border-radius:13px;padding:5px 9px;background:var(--danger-bg);color:var(--danger)}.status.ok{background:var(--success-bg);color:var(--success)}.meta{color:var(--muted);min-height:42px;margin:12px 0}.fields{display:grid;gap:10px}.fields input,.fields select{height:42px;border:1px solid var(--input-border);border-radius:8px;background:var(--input-bg);color:var(--text-primary);padding:0 11px}.actions{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}.actions button,.actions a{padding:9px 13px;border:1px solid var(--accent-secondary);border-radius:8px;background:var(--accent-soft);color:var(--accent-primary);text-decoration:none;cursor:pointer}.actions .primary{background:var(--accent-primary);border-color:var(--accent-primary);color:var(--button-primary-text)}.actions button:disabled{opacity:.55;cursor:wait}.test-result{display:none;white-space:pre-line;margin-top:12px;padding:10px 12px;border-radius:9px;font-size:13px;line-height:1.6}.test-result.show{display:block}.test-result.ok{background:var(--success-bg);border:1px solid var(--ok-line);color:var(--success)}.test-result.bad{background:var(--danger-bg);border:1px solid var(--bad-line);color:var(--danger)}.test-result.loading{background:var(--info-bg);border:1px solid var(--info);color:var(--info)}.toast{display:none;position:fixed;right:24px;bottom:24px;padding:13px 17px;border:1px solid var(--ok-line);background:var(--success-bg);border-radius:9px;color:var(--success)}.toast.bad{background:var(--danger-bg);border-color:var(--bad-line);color:var(--danger)}.qr-modal{display:none;position:fixed;inset:0;z-index:80;background:var(--overlay-bg);align-items:center;justify-content:center;padding:18px}.qr-modal.show{display:flex}.qr-box{width:min(420px,100%);text-align:center;background:var(--modal-bg);border:1px solid var(--accent-secondary);border-radius:18px;padding:22px;box-shadow:var(--card-shadow)}.qr-box img{display:block;width:min(280px,80vw);height:auto;margin:16px auto;background:#fff;border:10px solid #fff;border-radius:10px}.qr-box h2{color:var(--gold);margin:0}.qr-state{min-height:22px;color:var(--accent-primary)}.qr-close{float:right;border:0;background:transparent;color:var(--text-muted);font-size:24px;cursor:pointer}@media(max-width:850px){.shell{display:block}.side{display:none}.grid{grid-template-columns:1fr}.wrap{padding:12px}}
</style></head><body><div class="shell"><aside class="side"><div class="logo">◉ 影舟 MovieArk</div><div class="group">发现</div><a class="nav" href="/rankings">🏆 榜单</a><a class="nav" href="/explore">◉ 汇影</a><a class="nav" href="/search">⌕ 搜索</a><div class="group">订阅</div><a class="nav" href="/subscriptions">☷ 订阅列表</a><a class="nav" href="/tasks">▣ 订阅任务</a><a class="nav" href="/unlocks">◴ 解锁记录</a><div class="group">系统</div><a class="nav active" href="/authorizations">⌘ 授权中心</a><a class="nav" href="/settings">⚙ 业务设置</a><a class="nav" href="/telegram">✈ Telegram</a><a class="nav" href="/logs">▤ 日志中心</a><div class="theme-switch" data-theme-switch></div></aside><main><header class="top">⌘ 授权中心</header><section class="wrap"><p class="intro">账号、Cookie、API Key 和 Token 在这里集中管理。敏感值只保存在服务端，页面不会回显。</p><div class="grid" id="grid"></div></section></main></div><div id="toast" class="toast"></div><div id="qrModal" class="qr-modal"><div class="qr-box"><button id="qrClose" class="qr-close">×</button><h2>115 扫码登录</h2><p id="qrDevice"></p><img id="qrImage" alt="115登录二维码"><p id="qrState" class="qr-state">正在生成二维码…</p></div></div><script>
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const defs={hdhive:{name:'影巢',desc:'用于影巢资源查询、解锁和获取115分享链接。'},p115:{name:'115 网盘',desc:'统一用于115转存、ED2K与磁力云下载。'},emby:{name:'Emby',desc:'匹配媒体库现有项目与用户信息。'},tmdb:{name:'TMDB',desc:'用于汇影、海报、详情和榜单。流媒体榜单（Netflix / HBO Max / Prime Video / Disney+ / Apple TV+）通过 TMDB Watch Providers 提供，无需单独授权。'}};let state={};
function fields(id){if(id==='hdhive')return '';if(id==='p115')return '<select id="p115App"><option value="web">115生活_网页端</option><option value="ios">115生活_苹果端</option><option value="115ios">115管理_苹果端</option><option value="android">115生活_安卓端</option><option value="115android">115管理_安卓端</option><option value="ipad">115生活_苹果平板</option><option value="115ipad">115管理_苹果平板</option><option value="qandroid">115管理_安卓端(Q)</option><option value="qios">115管理_苹果端(Q)</option><option value="qipad">115管理_苹果平板(Q)</option><option value="os_windows">115生活_Windows端</option><option value="os_mac">115生活_macOS端</option><option value="os_linux">115生活_Linux端</option><option value="wechatmini">115生活_微信小程序</option><option value="alipaymini">115生活_支付宝小程序</option><option value="harmony">115鸿蒙端</option></select><input data-k="cookie" type="password" placeholder="115 Cookie（留空表示不修改）">';if(id==='emby')return '<input data-k="url" placeholder="Emby 地址"><input data-k="api_key" type="password" placeholder="API Key（留空表示不修改）"><input data-k="user_id" placeholder="User ID">';return '<input data-k="api_key" type="password" placeholder="API Key / Read Token（留空表示不修改）"><input data-k="language" placeholder="语言，例如 zh-CN">'}
function render(){ $('#grid').innerHTML=Object.entries(defs).map(([id,d])=>{const x=state[id]||{};return `<article class="card" data-id="${id}"><div class="head"><h2>${d.name}</h2><span class="status ${x.authorized||x.configured?'ok':''}">${x.authorized?'已授权':x.available?'已连接':x.configured?'已配置':'未配置'}</span></div><div class="meta">${d.desc}<br>${esc(x.summary||'')}</div><div class="fields">${fields(id)}</div><div class="actions">${id==='hdhive'?'<a class="primary" href="/oauth/login">打开授权页面</a>':'<button class="primary save">保存</button>'}<button class="test">${id==='hdhive'?'测试授权':id==='p115'?'测试Cookie':'测试连接'}</button>${id==='p115'?'<button class="qr">扫码登录</button>':''}</div><div class="test-result" id="test-${id}"></div></article>`}).join('');document.querySelectorAll('.card').forEach(card=>{const id=card.dataset.id;card.querySelectorAll('input').forEach(e=>{const v=(state[id]||{})[e.dataset.k];if(v&&!['api_key','cookie'].includes(e.dataset.k))e.value=v;e.addEventListener('input',()=>clearResult(id))});card.querySelector('.save')?.addEventListener('click',()=>save(card));card.querySelector('.test').onclick=()=>test(id);card.querySelector('.qr')?.addEventListener('click',startQr)})}
let qrTimer=null;function closeQr(){if(qrTimer){clearInterval(qrTimer);qrTimer=null}$('#qrModal').classList.remove('show')}$('#qrClose').onclick=closeQr;$('#qrModal').onclick=e=>{if(e.target===$('#qrModal'))closeQr()};async function startQr(){const app=$('#p115App')?.value||'web';$('#qrModal').classList.add('show');$('#qrState').textContent='正在生成二维码…';$('#qrImage').removeAttribute('src');const r=await fetch('/api/web/authorizations/p115/qr/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app})}),d=await r.json();if(!r.ok){$('#qrState').textContent=d.detail||'二维码生成失败';return}$('#qrDevice').textContent=d.device;$('#qrImage').src=d.qr_image;$('#qrState').textContent='请使用115手机端扫码，并在手机上确认登录';qrTimer=setInterval(async()=>{const x=await fetch('/api/web/authorizations/p115/qr/'+d.session_id),v=await x.json();$('#qrState').textContent=v.message||v.detail||'等待扫码';if(!x.ok||v.completed||v.status<0){clearInterval(qrTimer);qrTimer=null;if(v.completed){toast('115扫码授权成功');setTimeout(closeQr,1200);load()}}},2000)}async function load(){const r=await fetch('/api/web/authorizations'),d=await r.json();if(!r.ok)return toast(d.detail||'授权状态加载失败',true);state=d.providers||{};render()}function clearResult(id){const res=document.getElementById('test-'+id);if(res){res.className='test-result';res.textContent=''}}function setResult(id,kind,text){const res=document.getElementById('test-'+id);if(res){res.className='test-result show '+kind;res.textContent=text}}function refreshCard(id){const card=document.querySelector('[data-id="'+id+'"]');if(!card)return;const x=state[id]||{};const badge=card.querySelector('.status');if(badge){badge.className='status'+(x.authorized||x.configured?' ok':'');badge.textContent=x.authorized?'已授权':x.available?'已连接':x.configured?'已配置':'未配置'}const meta=card.querySelector('.meta');if(meta)meta.innerHTML=(defs[id]?.desc||'')+'<br>'+esc(x.summary||'')}async function refreshState(id){const r=await fetch('/api/web/authorizations'),d=await r.json();if(!r.ok)return;state=d.providers||{};refreshCard(id)}async function save(card){const id=card.dataset.id;clearResult(id);const body={};card.querySelectorAll('input').forEach(e=>body[e.dataset.k]=e.value);const r=await fetch('/api/web/authorizations/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)return toast(d.detail||'保存失败',true);toast('授权信息已安全保存');await load()}async function test(id){const card=document.querySelector('[data-id="'+id+'"]'),btn=card?.querySelector('.test');if(btn&&btn.disabled)return;if(btn){btn.disabled=true;btn.textContent='测试中…'}setResult(id,'loading','正在测试连接，请稍候…');const body={};card?.querySelectorAll('input').forEach(e=>body[e.dataset.k]=e.value);try{const r=await fetch('/api/web/authorizations/'+id+'/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(r.ok){setResult(id,'ok','✓ '+(d.message||'连接成功'));await refreshState(id)}else{setResult(id,'bad','✗ 测试失败\n原因：'+(d.detail||'未知错误'))}}catch(e){setResult(id,'bad','✗ 测试失败\n原因：'+(e.message||'网络错误'))}finally{if(btn){btn.disabled=false;btn.textContent=id==='hdhive'?'测试授权':id==='p115'?'测试Cookie':'测试连接'}}}function toast(m,b=false){const t=$('#toast');t.textContent=m;t.className='toast'+(b?' bad':'');t.style.display='block';setTimeout(()=>t.style.display='none',3500)}load();
</script></body></html>'''
